5: static bool validate_utf8(const char *b, size_t length) {
6:   const unsigned char *bytes = (const unsigned char *)b;
7:   for (size_t index = 0;;) {
8:     while (length - index >= sizeof(uint64_t)) {
9:       uint64_t word;
10:       std::memcpy(&word, bytes + index, sizeof(word));
11:       if ((word & UINT64_C(0x8080808080808080)) != 0) {
12:         break;
13:       }
14:       index += sizeof(word);
15:     }
16:     if (index >= length) {
17:       return true;
18:     }
19: 
20:     unsigned char byte1;
21:     do { // fast ASCII Path
22:       if (index >= length) {
23:         return true;
24:       }
25:       byte1 = bytes[index++];
26:     } while (byte1 < 0x80);
27:     if (byte1 < 0xE0) {
28:       // Two-byte form.
29:       if (index == length) {
30:         return false;
31:       }
32:       if (byte1 < 0xC2 || (bytes[index++] & 0xC0) != 0x80) {
33:         return false;
34:       }
35:     } else if (byte1 < 0xF0) {
36:       // Three-byte form.
37:       if (length - index < 2) {
38:         return false;
39:       }
40:       unsigned char byte2 = bytes[index++];
41:       if ((byte2 & 0xC0) != 0x80
42:           // Overlong? 5 most significant bits must not all be zero.
43:           || (byte1 == 0xE0 && byte2 < 0xA0)
44:           // Check for illegal surrogate codepoints.
45:           || (byte1 == 0xED && 0xA0 <= byte2)
46:           // Third byte trailing-byte test.
47:           || (bytes[index++] & 0xC0) != 0x80) {
48:         return false;
49:       }
50:     } else {
51: 
52:       // Four-byte form.
53:       if (length - index < 3) {
54:         return false;
55:       }
56:       int byte2 = bytes[index++];
57:       if ((byte2 & 0xC0) != 0x80
58:           // Check that 1 <= plane <= 16. Tricky optimized form of:
59:           // if (byte1 > (byte) 0xF4
60:           //     || byte1 == (byte) 0xF0 && byte2 < (byte) 0x90
61:           //     || byte1 == (byte) 0xF4 && byte2 > (byte) 0x8F)
62:           || (byte1 > 0xF4 || (byte1 == 0xF0 && byte2 < 0x90) || (byte1 == 0xF4 && byte2 > 0x8F))
63:           // Third byte trailing-byte test
64:           || (bytes[index++] & 0xC0) != 0x80
65:           // Fourth byte trailing-byte test
66:           || (bytes[index++] & 0xC0) != 0x80) {
67:         return false;
68:       }
69:     }
70:   }
71: }
