121:         ed & _mm512_cmpeq_epi8_mask(second_bit5, mask_20);
122:     const __mmask64 bad_f0 = f0 & _mm512_cmpeq_epi8_mask(
123:         _mm512_and_si512(next1, mask_f0), mask_80);
124:     const __mmask64 bad_f4 = f4 & ~_mm512_cmpeq_epi8_mask(
125:         _mm512_and_si512(next1, mask_30), zero);
126:     if ((bad_e0 | bad_ed | bad_f0 | bad_f4) != 0) {
127:       return false;
128:     }
129: 
130:     const uint64_t lead2_bits = static_cast<uint64_t>(lead2);
131:     const uint64_t lead3_bits = static_cast<uint64_t>(lead3);
132:     const uint64_t lead4_bits = static_cast<uint64_t>(lead4);
133:     const uint64_t expected =
134:         (lead2_bits << 1) |
135:         (lead3_bits << 1) | (lead3_bits << 2) |
136:         (lead4_bits << 1) | (lead4_bits << 2) | (lead4_bits << 3);
137:     const uint64_t expected_next =
138:         (lead2_bits >> 63) |
139:         (lead3_bits >> 63) | (lead3_bits >> 62) |
140:         (lead4_bits >> 63) | (lead4_bits >> 62) | (lead4_bits >> 61);
141:     const uint64_t continuation_bits =
142:         static_cast<uint64_t>(continuation);
143:     if (continuation_bits != (expected | pending)) {
144:       return false;
145:     }
146: 
147:     pending = expected_next;
148:     offset += 64;
149:   }
150: 
151:   return validate_utf8_scalar(bytes, length, offset,
152:                               static_cast<uint32_t>(pending));
153: }
154: #endif
