154:     if (continuation_bits != (static_cast<uint32_t>(expected) | pending)) {
155:       return false;
156:     }
157: 
158:     pending = static_cast<uint32_t>(expected >> 32);
159:     offset += 32;
160:   }
161: 
162:   return validate_utf8_scalar(bytes, length, offset, pending);
163: }
