102:         _mm512_and_si512(current, mask_c0), mask_80);
103:     const __mmask64 lead2 =
104:         _mm512_cmpeq_epi8_mask(_mm512_and_si512(current, mask_e0), mask_c0) &
105:         _mm512_cmpgt_epi8_mask(_mm512_and_si512(current, mask_1f), one);
106:     const __mmask64 lead3 = _mm512_cmpeq_epi8_mask(
107:         _mm512_and_si512(current, mask_f0), mask_e0);
108:     const __mmask64 high4 = _mm512_cmpeq_epi8_mask(
109:         _mm512_and_si512(current, mask_f8), mask_f0);
110:     const __mmask64 invalid4_low = _mm512_cmpgt_epi8_mask(
111:         _mm512_and_si512(current, mask_07), _mm512_set1_epi8(4));
112:     const __mmask64 lead4 = high4 & ~invalid4_low;
113:     const __mmask64 valid = ascii | continuation | lead2 | lead3 | lead4;
114: 
115:     if (valid != UINT64_MAX) {
116:       return false;
117:     }
118: 
119:     const __mmask64 e0 = _mm512_cmpeq_epi8_mask(
120:         current, _mm512_set1_epi8(static_cast<char>(0xE0)));
121:     const __mmask64 ed = _mm512_cmpeq_epi8_mask(
122:         current, _mm512_set1_epi8(static_cast<char>(0xED)));
123:     const __mmask64 f0 = _mm512_cmpeq_epi8_mask(
124:         current, _mm512_set1_epi8(static_cast<char>(0xF0)));
125:     const __mmask64 f4 = _mm512_cmpeq_epi8_mask(current, mask_f4);
126: 
127:     const __m512i second_bit5 = _mm512_and_si512(next1, mask_20);
128:     const __mmask64 bad_e0 = e0 & _mm512_cmpeq_epi8_mask(second_bit5, zero);
129:     const __mmask64 bad_ed =
130:         ed & _mm512_cmpeq_epi8_mask(second_bit5, mask_20);
131:     const __mmask64 bad_f0 = f0 & _mm512_cmpeq_epi8_mask(
132:         _mm512_and_si512(next1, mask_f0), mask_80);
133:     const __mmask64 bad_f4 = f4 & ~_mm512_cmpeq_epi8_mask(
134:         _mm512_and_si512(next1, mask_30), zero);
135:     if ((bad_e0 | bad_ed | bad_f0 | bad_f4) != 0) {
136:       return false;
137:     }
138: 
139:     const uint64_t lead2_bits = static_cast<uint64_t>(lead2);
140:     const uint64_t lead3_bits = static_cast<uint64_t>(lead3);
141:     const uint64_t lead4_bits = static_cast<uint64_t>(lead4);
142:     const uint64_t expected =
143:         (lead2_bits << 1) |
144:         (lead3_bits << 1) | (lead3_bits << 2) |
145:         (lead4_bits << 1) | (lead4_bits << 2) | (lead4_bits << 3);
146:     const uint64_t expected_next =
147:         (lead2_bits >> 63) |
148:         (lead3_bits >> 63) | (lead3_bits >> 62) |
149:         (lead4_bits >> 63) | (lead4_bits >> 62) | (lead4_bits >> 61);
150:     const uint64_t continuation_bits =
151:         static_cast<uint64_t>(continuation);
152:     if (continuation_bits != (expected | pending)) {
153:       return false;
154:     }
155: 
156:     pending = expected_next;
157:     offset += 64;
158:   }
159: 
160:   return validate_utf8_scalar(bytes, length, offset,
161:                               static_cast<uint32_t>(pending));
162: }
163: #endif
