10: static bool validate_utf8(const char *b, size_t length) {
11:   const unsigned char *bytes = (const unsigned char *)b;
12:   size_t index = 0;
13: 
14:   while (index < length) {
15:     // Check complete scalar-sized words; never read beyond the input.
16:     while (length - index >= sizeof(uint64_t)) {
17:       uint64_t word;
18:       std::memcpy(&word, bytes + index, sizeof(word));
19:       if ((word & UINT64_C(0x8080808080808080)) != 0) {
20:         break;
21:       }
22:       index += sizeof(word);
23:     }
24: 
25:     while (index < length && bytes[index] < 0x80) {
26:       ++index;
27:     }
28:     if (index == length) {
29:       return true;
30:     }
31: 
32:     const unsigned char lead = bytes[index++];
33:     if (lead < 0xC2 || lead > 0xF4) {
34:       return false;
35:     }
36: 
37:     unsigned int remaining = 1u + static_cast<unsigned int>(lead >= 0xE0) +
38:                              static_cast<unsigned int>(lead >= 0xF0);
39:     uint32_t lower = 0x80u +
40:                      (static_cast<uint32_t>(lead == 0xE0) << 5) +
41:                      (static_cast<uint32_t>(lead == 0xF0) << 4);
42:     uint32_t upper = 0xBFu -
43:                      (static_cast<uint32_t>(lead == 0xED) << 5) -
44:                      (static_cast<uint32_t>(lead == 0xF4) * 0x30u);
45: 
46:     while (remaining != 0) {
47:       if (index == length) {
48:         return false;
49:       }
50:       const uint32_t delta = static_cast<uint32_t>(bytes[index++]) - lower;
51:       if (delta > upper - lower) {
52:         return false;
53:       }
54:       lower = 0x80u;
55:       upper = 0xBFu;
56:       --remaining;
57:     }
58:   }
59: 
60:   return true;
61: }
62: 
63: extern "C" void run(const void *input1, const void *input2, void *output,
64:                     int n, int parameter, int threads) {
65:   *(uint32_t *)output = validate_utf8((const char *)input1, n);
66: }

