4: 
5: static bool validate_utf8(const char *b, size_t length) {
6:   const unsigned char *bytes = (const unsigned char *)b;
7:   size_t index = 0;
8:   unsigned remaining = 0;
9:   unsigned char next_min = 0x80;
10:   unsigned char next_max = 0xBF;
11: 
12:   while (index < length) {
13:     if (remaining == 0) {
14:       // Consume ordinary ASCII without entering the lead-byte classifier.
15:       while (index < length && bytes[index] < 0x80) {
16:         ++index;
17:       }
18:       if (index == length) {
19:         return true;
20:       }
21: 
22:       const unsigned char lead = bytes[index++];
23:       if (lead < 0xC2 || lead > 0xF4) {
24:         return false;
25:       }
26: 
27:       // Derive continuation count and first-byte bounds from predicates.
28:       remaining = 1u + static_cast<unsigned>(lead >= 0xE0) +
29:                   static_cast<unsigned>(lead >= 0xF0);
30:       next_min = static_cast<unsigned char>(
31:           0x80u + static_cast<unsigned>(lead == 0xE0) * 0x20u +
32:           static_cast<unsigned>(lead == 0xF0) * 0x10u);
33:       next_max = static_cast<unsigned char>(
34:           0xBFu - static_cast<unsigned>(lead == 0xED) * 0x20u -
35:           static_cast<unsigned>(lead == 0xF4) * 0x30u);
36: 
37:       if (index == length) {
38:         return false;
39:       }
40:     }
41: 
42:     const unsigned value = bytes[index++];
43:     const unsigned minimum = next_min;
44:     const unsigned maximum = next_max;
45:     if (value - minimum > maximum - minimum) {
46:       return false;
47:     }
48:     --remaining;
49:     next_min = 0x80;
50:     next_max = 0xBF;
51:   }
52: 
53:   return remaining == 0;
54: }
