34: static bool validate_utf8_scalar_tail(const unsigned char *bytes, size_t length,
35:                                       size_t index, uint32_t pending,
36:                                       unsigned int restriction) {
37:   unsigned int pending_count = ((pending & 1u) != 0u) +
38:                                ((pending & 2u) != 0u) +
39:                                ((pending & 4u) != 0u);
40:   bool check_restricted_second = restriction != kRestrictionNone;
41: 
42:   while (index < length) {
43:     const unsigned char byte1 = bytes[index++];
44: 
45:     if (pending_count != 0) {
46:       if ((byte1 & 0xC0) != 0x80) {
47:         return false;
48:       }
49:       if (check_restricted_second &&
50:           !restricted_second_byte_valid(byte1, restriction)) {
51:         return false;
52:       }
53:       check_restricted_second = false;
54:       --pending_count;
55:       continue;
56:     }
57: 
58:     if (byte1 <= 0x7F) {
59:       continue;
60:     }
61: 
62:     if (byte1 >= 0xC2 && byte1 <= 0xDF) {
63:       if (length - index < 1) {
64:         return false;
65:       }
66:       if ((bytes[index++] & 0xC0) != 0x80) {
67:         return false;
68:       }
69:     } else if (byte1 >= 0xE0 && byte1 <= 0xEF) {
70:       if (length - index < 2) {
71:         return false;
72:       }
73:       const unsigned char byte2 = bytes[index++];
74:       const unsigned char byte3 = bytes[index++];
75:       if ((byte2 & 0xC0) != 0x80 ||
76:           (byte1 == 0xE0 && byte2 < 0xA0) ||
77:           (byte1 == 0xED && byte2 >= 0xA0) ||
78:           (byte3 & 0xC0) != 0x80) {
79:         return false;
80:       }
81:     } else if (byte1 >= 0xF0 && byte1 <= 0xF4) {
82:       if (length - index < 3) {
83:         return false;
84:       }
85:       const unsigned char byte2 = bytes[index++];
86:       const unsigned char byte3 = bytes[index++];
87:       const unsigned char byte4 = bytes[index++];
88:       if ((byte2 & 0xC0) != 0x80 ||
89:           (byte1 == 0xF0 && byte2 < 0x90) ||
90:           (byte1 == 0xF4 && byte2 >= 0x90) ||
91:           (byte3 & 0xC0) != 0x80 ||
92:           (byte4 & 0xC0) != 0x80) {
93:         return false;
94:       }
95:     } else {
96:       return false;
97:     }
98:   }
