103: static inline __attribute__((target("avx2"), always_inline)) bool
104: validate_avx2_block(const unsigned char *bytes, uint32_t *pending,
105:                     unsigned int *restriction) {
106:   const __m256i value = _mm256_loadu_si256(
107:       reinterpret_cast<const __m256i *>(bytes));
108:   const uint32_t non_ascii_mask = static_cast<uint32_t>(
109:       _mm256_movemask_epi8(value));
110: 
111:   if (non_ascii_mask == 0 && *pending == 0 &&
112:       *restriction == kRestrictionNone) {
113:     return true;
114:   }
115: 
116:   // Signed constants represent their corresponding byte values for cmpgt.
117:   const __m256i c0 = _mm256_set1_epi8(-64);
118:   const __m256i byte80 = _mm256_set1_epi8(-128);
119:   const __m256i c1 = _mm256_set1_epi8(-63);
120:   const __m256i e0 = _mm256_set1_epi8(-32);
121:   const __m256i df = _mm256_set1_epi8(-33);
122:   const __m256i f0 = _mm256_set1_epi8(-16);
123:   const __m256i ef = _mm256_set1_epi8(-17);
124:   const __m256i f5 = _mm256_set1_epi8(-11);
125:   const __m256i a0 = _mm256_set1_epi8(-96);
126:   const __m256i byte90 = _mm256_set1_epi8(-112);
127: 
128:   const __m256i continuation = _mm256_cmpeq_epi8(
129:       _mm256_and_si256(value, c0), byte80);
130:   const __m256i lead2 = _mm256_and_si256(
131:       _mm256_cmpgt_epi8(value, c1), _mm256_cmpgt_epi8(e0, value));
132:   const __m256i lead3 = _mm256_and_si256(
133:       _mm256_cmpgt_epi8(value, df), _mm256_cmpgt_epi8(f0, value));
134:   const __m256i lead4 = _mm256_and_si256(
135:       _mm256_cmpgt_epi8(value, ef), _mm256_cmpgt_epi8(f5, value));
136: 
137:   const uint32_t continuation_mask = static_cast<uint32_t>(
138:       _mm256_movemask_epi8(continuation));
139:   const uint32_t lead2_mask = static_cast<uint32_t>(
140:       _mm256_movemask_epi8(lead2));
141:   const uint32_t lead3_mask = static_cast<uint32_t>(
142:       _mm256_movemask_epi8(lead3));
143:   const uint32_t lead4_mask = static_cast<uint32_t>(
144:       _mm256_movemask_epi8(lead4));
145:   const uint32_t ascii_mask = ~non_ascii_mask;
146:   const uint32_t class_mask = ascii_mask | continuation_mask | lead2_mask |
147:                               lead3_mask | lead4_mask;
148:   if (class_mask != 0xFFFFFFFFu) {
149:     return false;
150:   }
151: 
152:   if (*restriction != kRestrictionNone &&
153:       !restricted_second_byte_valid(bytes[0], *restriction)) {
154:     return false;
155:   }
156: 
157:   const uint32_t e0_mask = static_cast<uint32_t>(_mm256_movemask_epi8(
158:       _mm256_cmpeq_epi8(value, e0)));
159:   const uint32_t ed_mask = static_cast<uint32_t>(_mm256_movemask_epi8(
160:       _mm256_cmpeq_epi8(value, _mm256_set1_epi8(-19))));
161:   const uint32_t f0_mask = static_cast<uint32_t>(_mm256_movemask_epi8(
162:       _mm256_cmpeq_epi8(value, f0)));
163:   const uint32_t f4_mask = static_cast<uint32_t>(_mm256_movemask_epi8(
164:       _mm256_cmpeq_epi8(value, _mm256_set1_epi8(-12))));
165:   const uint32_t below_a0 = static_cast<uint32_t>(_mm256_movemask_epi8(
166:       _mm256_cmpgt_epi8(a0, value)));
167:   const uint32_t below_90 = static_cast<uint32_t>(_mm256_movemask_epi8(
168:       _mm256_cmpgt_epi8(byte90, value)));
169:   const uint32_t invalid_restricted_second =
170:       ((e0_mask << 1) & below_a0) |
171:       ((ed_mask << 1) & ~below_a0) |
172:       ((f0_mask << 1) & below_90) |
173:       ((f4_mask << 1) & ~below_90);
174:   if (invalid_restricted_second != 0) {
175:     return false;
176:   }
177: 
178:   const uint64_t expected_continuations =
179:       (static_cast<uint64_t>(lead2_mask | lead3_mask | lead4_mask) << 1) |
180:       (static_cast<uint64_t>(lead3_mask | lead4_mask) << 2) |
181:       (static_cast<uint64_t>(lead4_mask) << 3);
182:   const uint32_t expected_here =
183:       static_cast<uint32_t>(expected_continuations) | *pending;
184:   if (continuation_mask != expected_here) {
185:     return false;
186:   }
187: 
188:   *pending = static_cast<uint32_t>(expected_continuations >> 32);
189:   if ((e0_mask & 0x80000000u) != 0) {
190:     *restriction = kRestrictionE0;
191:   } else if ((ed_mask & 0x80000000u) != 0) {
192:     *restriction = kRestrictionED;
193:   } else if ((f0_mask & 0x80000000u) != 0) {
194:     *restriction = kRestrictionF0;
195:   } else if ((f4_mask & 0x80000000u) != 0) {
196:     *restriction = kRestrictionF4;
197:   } else {
198:     *restriction = kRestrictionNone;
199:   }
200:   return true;
201: }
