204: static bool validate_utf8_avx2(const unsigned char *bytes, size_t length) {
205:   size_t offset = 0;
206:   uint32_t pending = 0;
207:   unsigned int restriction = kRestrictionNone;
208: 
209:   while (length - offset >= 64) {
210:     if (!validate_avx2_block(bytes + offset, &pending, &restriction) ||
211:         !validate_avx2_block(bytes + offset + 32, &pending, &restriction)) {
212:       return false;
213:     }
214:     offset += 64;
215:   }
216: 
217:   while (length - offset >= 32) {
218:     if (!validate_avx2_block(bytes + offset, &pending, &restriction)) {
219:       return false;
220:     }
221:     offset += 32;
222:   }
