11: enum {
12:   kRestrictionNone = 0,
13:   kRestrictionE0 = 1,
14:   kRestrictionED = 2,
15:   kRestrictionF0 = 3,
16:   kRestrictionF4 = 4
17: };
18: 
19: static bool restricted_second_byte_valid(unsigned char byte, unsigned int restriction) {
20:   switch (restriction) {
21:   case kRestrictionE0:
22:     return byte >= 0xA0;
23:   case kRestrictionED:
24:     return byte < 0xA0;
25:   case kRestrictionF0:
26:     return byte >= 0x90;
27:   case kRestrictionF4:
28:     return byte < 0x90;
29:   default:
30:     return true;
31:   }
32: }
