103: static inline __attribute__((target("avx2"), always_inline)) bool
104: validate_avx2_block(const unsigned char *bytes, uint32_t *pending,
105:                     unsigned int *restriction) {
106:   const __m256i value = _mm256_loadu_si256(
107:       reinterpret_cast<const __m256i *>(bytes));
108: 
109:   // Signed constants represent their corresponding byte values for cmpgt.
110:   const __m256i c0 = _mm256_set1_epi8(-64);
111:   const __m256i byte80 = _mm256_set1_epi8(-128);
112:   const __m256i c1 = _mm256_set1_epi8(-63);
113:   const __m256i e0 = _mm256_set1_epi8(-32);
114:   const __m256i df = _mm256_set1_epi8(-33);
115:   const __m256i f0 = _mm256_set1_epi8(-16);
116:   const __m256i ef = _mm256_set1_epi8(-17);
117:   const __m256i f5 = _mm256_set1_epi8(-11);
118:   const __m256i a0 = _mm256_set1_epi8(-96);
119:   const __m256i byte90 = _mm256_set1_epi8(-112);
120: 
121:   const __m256i continuation = _mm256_cmpeq_epi8(
122:       _mm256_and_si256(value, c0), byte80);
123:   const __m256i lead2 = _mm256_and_si256(
124:       _mm256_cmpgt_epi8(value, c1), _mm256_cmpgt_epi8(e0, value));
125:   const __m256i lead3 = _mm256_and_si256(
126:       _mm256_cmpgt_epi8(value, df), _mm256_cmpgt_epi8(f0, value));
127:   const __m256i lead4 = _mm256_and_si256(
128:       _mm256_cmpgt_epi8(value, ef), _mm256_cmpgt_epi8(f5, value));
129: 
130:   const uint32_t non_ascii_mask = static_cast<uint32_t>(
131:       _mm256_movemask_epi8(value));
132:   const uint32_t continuation_mask = static_cast<uint32_t>(
133:       _mm256_movemask_epi8(continuation));
134:   const uint32_t lead2_mask = static_cast<uint32_t>(
135:       _mm256_movemask_epi8(lead2));
136:   const uint32_t lead3_mask = static_cast<uint32_t>(
137:       _mm256_movemask_epi8(lead3));
138:   const uint32_t lead4_mask = static_cast<uint32_t>(
139:       _mm256_movemask_epi8(lead4));
140:   const uint32_t ascii_mask = ~non_ascii_mask;
141:   const uint32_t class_mask = ascii_mask | continuation_mask | lead2_mask |
142:                               lead3_mask | lead4_mask;
143:   if (class_mask != 0xFFFFFFFFu) {
144:     return false;
145:   }
146: 
147:   if (*restriction != kRestrictionNone &&
148:       !restricted_second_byte_valid(bytes[0], *restriction)) {
149:     return false;
150:   }
151: 
152:   const uint32_t e0_mask = static_cast<uint32_t>(_mm256_movemask_epi8(
153:       _mm256_cmpeq_epi8(value, e0)));
154:   const uint32_t ed_mask = static_cast<uint32_t>(_mm256_movemask_epi8(
155:       _mm256_cmpeq_epi8(value, _mm256_set1_epi8(-19))));
156:   const uint32_t f0_mask = static_cast<uint32_t>(_mm256_movemask_epi8(
157:       _mm256_cmpeq_epi8(value, f0)));
158:   const uint32_t f4_mask = static_cast<uint32_t>(_mm256_movemask_epi8(
159:       _mm256_cmpeq_epi8(value, _mm256_set1_epi8(-12))));
160:   const uint32_t below_a0 = static_cast<uint32_t>(_mm256_movemask_epi8(
161:       _mm256_cmpgt_epi8(a0, value)));
162:   const uint32_t below_90 = static_cast<uint32_t>(_mm256_movemask_epi8(
163:       _mm256_cmpgt_epi8(byte90, value)));
164:   const uint32_t invalid_restricted_second =
165:       ((e0_mask << 1) & below_a0) |
166:       ((ed_mask << 1) & ~below_a0) |
167:       ((f0_mask << 1) & below_90) |
168:       ((f4_mask << 1) & ~below_90);
169:   if (invalid_restricted_second != 0) {
170:     return false;
171:   }
172: 
173:   const uint64_t expected_continuations =
174:       (static_cast<uint64_t>(lead2_mask | lead3_mask | lead4_mask) << 1) |
175:       (static_cast<uint64_t>(lead3_mask | lead4_mask) << 2) |
176:       (static_cast<uint64_t>(lead4_mask) << 3);
177:   const uint32_t expected_here =
178:       static_cast<uint32_t>(expected_continuations) | *pending;
179:   if (continuation_mask != expected_here) {
180:     return false;
181:   }
182: 
183:   *pending = static_cast<uint32_t>(expected_continuations >> 32);
184:   if ((e0_mask & 0x80000000u) != 0) {
185:     *restriction = kRestrictionE0;
186:   } else if ((ed_mask & 0x80000000u) != 0) {
187:     *restriction = kRestrictionED;
188:   } else if ((f0_mask & 0x80000000u) != 0) {
189:     *restriction = kRestrictionF0;
190:   } else if ((f4_mask & 0x80000000u) != 0) {
191:     *restriction = kRestrictionF4;
192:   } else {
193:     *restriction = kRestrictionNone;
194:   }
195:   return true;
196: }
197: 
198: __attribute__((target("avx2")))
199: static bool validate_utf8_avx2(const unsigned char *bytes, size_t length) {
200:   size_t offset = 0;
201:   uint32_t pending = 0;
202:   unsigned int restriction = kRestrictionNone;
203: 
204:   while (length - offset >= 64) {
205:     if (!validate_avx2_block(bytes + offset, &pending, &restriction) ||
206:         !validate_avx2_block(bytes + offset + 32, &pending, &restriction)) {
207:       return false;
208:     }
209:     offset += 64;
210:   }
211: 
212:   while (length - offset >= 32) {
213:     if (!validate_avx2_block(bytes + offset, &pending, &restriction)) {
214:       return false;
215:     }
216:     offset += 32;
217:   }
218: 
219:   return validate_utf8_scalar_tail(bytes, length, offset, pending, restriction);
220: }
221: 
222: static bool validate_utf8(const char *b, size_t length) {
223:   return validate_utf8_avx2(reinterpret_cast<const unsigned char *>(b), length);
224: }
