78:   const __m512i mask_f0 = _mm512_set1_epi8(static_cast<char>(0xF0));
79:   const __m512i mask_f4 = _mm512_set1_epi8(static_cast<char>(0xF4));
80:   const __m512i mask_f8 = _mm512_set1_epi8(static_cast<char>(0xF8));
81: 
82:   const __m512i current = _mm512_loadu_si512(bytes);
83:   const __mmask64 ascii = _mm512_cmpeq_epi8_mask(
84:       _mm512_and_si512(current, mask_80), zero);
85: 
86:   // With no carried continuation, an all-ASCII block needs no shifted load.
87:   if (pending == 0 && ascii == static_cast<__mmask64>(~uint64_t(0))) {
88:     return true;
89:   }
90: 
91:   const __m512i next1 = _mm512_loadu_si512(bytes + 1);
92:   const __mmask64 continuation = _mm512_cmpeq_epi8_mask(
93:       _mm512_and_si512(current, mask_c0), mask_80);
94:   const __mmask64 lead2 =
95:       _mm512_cmpeq_epi8_mask(_mm512_and_si512(current, mask_e0), mask_c0) &
96:       _mm512_cmpgt_epi8_mask(_mm512_and_si512(current, mask_1f), one);
97:   const __mmask64 lead3 = _mm512_cmpeq_epi8_mask(
98:       _mm512_and_si512(current, mask_f0), mask_e0);
99:   const __mmask64 high4 = _mm512_cmpeq_epi8_mask(
100:       _mm512_and_si512(current, mask_f8), mask_f0);
101:   const __mmask64 invalid4_low = _mm512_cmpgt_epi8_mask(
102:       _mm512_and_si512(current, mask_07), four);
103:   const __mmask64 lead4 = high4 & ~invalid4_low;
104:   const __mmask64 valid = ascii | continuation | lead2 | lead3 | lead4;
105: 
106:   if (valid != static_cast<__mmask64>(~uint64_t(0))) {
107:     return false;
108:   }
109: 
110:   const __mmask64 e0 = _mm512_cmpeq_epi8_mask(
111:       current, _mm512_set1_epi8(static_cast<char>(0xE0)));
112:   const __mmask64 ed = _mm512_cmpeq_epi8_mask(
113:       current, _mm512_set1_epi8(static_cast<char>(0xED)));
114:   const __mmask64 f0 = _mm512_cmpeq_epi8_mask(
115:       current, _mm512_set1_epi8(static_cast<char>(0xF0)));
116:   const __mmask64 f4 = _mm512_cmpeq_epi8_mask(current, mask_f4);
117: 
118:   const __mmask64 bad_e0 = e0 & ~_mm512_cmpeq_epi8_mask(
119:       _mm512_and_si512(next1, mask_20), zero);
120:   const __mmask64 bad_ed = ed & _mm512_cmpeq_epi8_mask(
121:       _mm512_and_si512(next1, mask_20), mask_20);
122:   const __mmask64 bad_f0 = f0 & ~_mm512_cmpeq_epi8_mask(
123:       _mm512_and_si512(next1, mask_f0), mask_80);
124:   const __mmask64 bad_f4 = f4 & ~_mm512_cmpeq_epi8_mask(
125:       _mm512_and_si512(next1, mask_30), zero);
126:   if ((bad_e0 | bad_ed | bad_f0 | bad_f4) != 0) {
127:     return false;
128:   }
129: 
130:   const uint64_t lead2_bits = static_cast<uint64_t>(lead2);
131:   const uint64_t lead3_bits = static_cast<uint64_t>(lead3);
132:   const uint64_t lead4_bits = static_cast<uint64_t>(lead4);
133:   const unsigned __int128 expected =
134:       (static_cast<unsigned __int128>(lead2_bits) << 1) |
135:       (static_cast<unsigned __int128>(lead3_bits) << 1) |
136:       (static_cast<unsigned __int128>(lead3_bits) << 2) |
137:       (static_cast<unsigned __int128>(lead4_bits) << 1) |
138:       (static_cast<unsigned __int128>(lead4_bits) << 2) |
139:       (static_cast<unsigned __int128>(lead4_bits) << 3);
140:   const uint64_t expected_here = static_cast<uint64_t>(expected);
141:   if (static_cast<uint64_t>(continuation) != (expected_here | pending)) {
142:     return false;
143:   }
144: 
145:   pending = static_cast<uint64_t>(expected >> 64);
146:   return true;
147: }
