149: __attribute__((target("avx512f,avx512bw")))
150: static bool validate_utf8_avx512(const unsigned char *bytes, size_t length) {
151:   size_t offset = 0;
152:   uint64_t pending = 0;
153: 
154:   // Each block validator reads 64 current bytes and one following byte.
155:   // Two blocks are safe when at least 129 bytes remain.
156:   while (length - offset >= 129) {
157:     if (!validate_utf8_avx512_block(bytes + offset, pending) ||
158:         !validate_utf8_avx512_block(bytes + offset + 64, pending)) {
159:       return false;
160:     }
161:     offset += 128;
162:   }
163: 
164:   while (length - offset >= 65) {
165:     if (!validate_utf8_avx512_block(bytes + offset, pending)) {
166:       return false;
167:     }
168:     offset += 64;
169:   }
170: 
171:   return validate_utf8_scalar(bytes, length, offset,
172:                               static_cast<uint32_t>(pending));
173: }
174: #endif
