176: static bool validate_utf8(const char *input, size_t length) {
177:   const unsigned char *bytes = reinterpret_cast<const unsigned char *>(input);
178: #if UTF8_HAS_AVX512BW_TARGET
179:   if (length >= 65) {
180:     // A SIMD rejection is verified from the beginning by the scalar reference
181:     // path. SIMD acceptance still requires all vector checks and the safe tail.
182:     if (validate_utf8_avx512(bytes, length)) {
183:       return true;
184:     }
185:     return validate_utf8_scalar(bytes, length, 0, 0);
186:   }
187: #endif
188:   return validate_utf8_scalar(bytes, length, 0, 0);
189: }
