17: static bool validate_utf8_scalar(const unsigned char *bytes, size_t length,
18:                                  size_t index, uint32_t pending) {
19:   while (pending != 0) {
20:     if (index >= length || (bytes[index++] & 0xC0u) != 0x80u) {
21:       return false;
22:     }
23:     pending >>= 1;
24:   }
25: 
26:   while (index < length) {
27:     const unsigned char byte1 = bytes[index++];
28:     if (byte1 < 0x80) {
29:       continue;
30:     }
31:     if (byte1 < 0xE0) {
32:       if (byte1 < 0xC2 || index >= length ||
33:           (bytes[index++] & 0xC0u) != 0x80u) {
34:         return false;
35:       }
36:     } else if (byte1 < 0xF0) {
37:       if (length - index < 2) {
38:         return false;
39:       }
40:       const unsigned char byte2 = bytes[index++];
41:       if ((byte2 & 0xC0u) != 0x80u ||
42:           (byte1 == 0xE0 && byte2 < 0xA0) ||
43:           (byte1 == 0xED && byte2 >= 0xA0) ||
44:           (bytes[index++] & 0xC0u) != 0x80u) {
45:         return false;
46:       }
47:     } else {
48:       if (length - index < 3) {
49:         return false;
50:       }
51:       const unsigned char byte2 = bytes[index++];
52:       if ((byte2 & 0xC0u) != 0x80u || byte1 > 0xF4 ||
53:           (byte1 == 0xF0 && byte2 < 0x90) ||
54:           (byte1 == 0xF4 && byte2 > 0x8F) ||
55:           (bytes[index++] & 0xC0u) != 0x80u ||
56:           (bytes[index++] & 0xC0u) != 0x80u) {
57:         return false;
58:       }
59:     }
60:   }
61:   return true;
62: }
