66: static bool validate_utf8_avx2(const unsigned char *bytes, size_t length) {
67:   size_t offset = 0;
68:   uint32_t pending = 0;
69:   const __m256i zero = _mm256_setzero_si256();
70:   const __m256i one = _mm256_set1_epi8(1);
71:   const __m256i four = _mm256_set1_epi8(4);
72:   const __m256i mask_07 = _mm256_set1_epi8(7);
73:   const __m256i mask_1f = _mm256_set1_epi8(0x1F);
74:   const __m256i mask_20 = _mm256_set1_epi8(0x20);
75:   const __m256i mask_30 = _mm256_set1_epi8(0x30);
76:   const __m256i mask_80 = _mm256_set1_epi8(static_cast<char>(0x80));
77:   const __m256i mask_c0 = _mm256_set1_epi8(static_cast<char>(0xC0));
78:   const __m256i mask_e0 = _mm256_set1_epi8(static_cast<char>(0xE0));
79:   const __m256i mask_f0 = _mm256_set1_epi8(static_cast<char>(0xF0));
80:   const __m256i mask_f8 = _mm256_set1_epi8(static_cast<char>(0xF8));
81:   const __m256i mask_f4 = _mm256_set1_epi8(static_cast<char>(0xF4));
82: 
83:   // The shifted load ends at offset + 32, so 33 remaining bytes are sufficient.
84:   // The final at-most-32 bytes are handled by the scalar validator below.
85:   while (length - offset >= 33) {
86:     const __m256i current = _mm256_loadu_si256(
87:         reinterpret_cast<const __m256i *>(bytes + offset));
88:     const __m256i next1 = _mm256_loadu_si256(
89:         reinterpret_cast<const __m256i *>(bytes + offset + 1));
90: 
91:     const __m256i ascii = _mm256_cmpeq_epi8(
92:         _mm256_and_si256(current, mask_80), zero);
93:     const __m256i continuation = _mm256_cmpeq_epi8(
94:         _mm256_and_si256(current, mask_c0), mask_80);
95:     const __m256i lead2 = _mm256_and_si256(
96:         _mm256_cmpeq_epi8(_mm256_and_si256(current, mask_e0), mask_c0),
97:         _mm256_cmpgt_epi8(_mm256_and_si256(current, mask_1f), one));
98:     const __m256i lead3 = _mm256_cmpeq_epi8(
99:         _mm256_and_si256(current, mask_f0), mask_e0);
100:     const __m256i high4 = _mm256_cmpeq_epi8(
101:         _mm256_and_si256(current, mask_f8), mask_f0);
102:     const __m256i invalid4_low = _mm256_cmpgt_epi8(
103:         _mm256_and_si256(current, mask_07), four);
104:     const __m256i lead4 = _mm256_andnot_si256(invalid4_low, high4);
105:     const __m256i valid = _mm256_or_si256(
106:         _mm256_or_si256(ascii, continuation),
107:         _mm256_or_si256(lead2, _mm256_or_si256(lead3, lead4)));
108: 
109:     if (_mm256_movemask_epi8(valid) != -1) {
110:       return false;
111:     }
112: 
113:     const __m256i e0 = _mm256_cmpeq_epi8(
114:         current, _mm256_set1_epi8(static_cast<char>(0xE0)));
115:     const __m256i ed = _mm256_cmpeq_epi8(
116:         current, _mm256_set1_epi8(static_cast<char>(0xED)));
117:     const __m256i f0 = _mm256_cmpeq_epi8(
118:         current, _mm256_set1_epi8(static_cast<char>(0xF0)));
119:     const __m256i f4 = _mm256_cmpeq_epi8(current, mask_f4);
120: 
121:     const __m256i second_bit5 = _mm256_and_si256(next1, mask_20);
122:     const __m256i bad_e0 = _mm256_and_si256(
123:         e0, _mm256_cmpeq_epi8(second_bit5, zero));
124:     const __m256i bad_ed = _mm256_and_si256(
125:         ed, _mm256_cmpeq_epi8(second_bit5, mask_20));
126: 
127:     // F0 permits 90-BF; its invalid continuation range is exactly 80-8F.
128:     const __m256i bad_f0 = _mm256_and_si256(
129:         f0, _mm256_cmpeq_epi8(_mm256_and_si256(next1, mask_f0), mask_80));
130:     // F4 permits 80-8F; any of bits 0x30 set makes the second byte too large.
131:     const __m256i bad_f4 = _mm256_andnot_si256(
132:         _mm256_cmpeq_epi8(_mm256_and_si256(next1, mask_30), zero), f4);
133:     const __m256i bad_second = _mm256_or_si256(
134:         _mm256_or_si256(bad_e0, bad_ed), _mm256_or_si256(bad_f0, bad_f4));
135:     if (_mm256_movemask_epi8(bad_second) != 0) {
136:       return false;
137:     }
138: 
139:     const uint32_t lead2_bits =
140:         static_cast<uint32_t>(_mm256_movemask_epi8(lead2));
141:     const uint32_t lead3_bits =
142:         static_cast<uint32_t>(_mm256_movemask_epi8(lead3));
143:     const uint32_t lead4_bits =
144:         static_cast<uint32_t>(_mm256_movemask_epi8(lead4));
145:     const uint64_t expected =
146:         (static_cast<uint64_t>(lead2_bits) << 1) |
147:         (static_cast<uint64_t>(lead3_bits) << 1) |
148:         (static_cast<uint64_t>(lead3_bits) << 2) |
149:         (static_cast<uint64_t>(lead4_bits) << 1) |
150:         (static_cast<uint64_t>(lead4_bits) << 2) |
151:         (static_cast<uint64_t>(lead4_bits) << 3);
152:     const uint32_t continuation_bits =
153:         static_cast<uint32_t>(_mm256_movemask_epi8(continuation));
154:     if (continuation_bits != (static_cast<uint32_t>(expected) | pending)) {
155:       return false;
156:     }
