65: __attribute__((target("avx512f,avx512bw")))
66: static bool validate_utf8_avx512bw(const unsigned char *bytes, size_t length) {
67:   size_t offset = 0;
68:   uint64_t pending = 0;
69:   const __m512i zero = _mm512_setzero_si512();
70:   const __m512i one = _mm512_set1_epi8(1);
71:   const __m512i mask_07 = _mm512_set1_epi8(7);
72:   const __m512i mask_1f = _mm512_set1_epi8(0x1F);
73:   const __m512i mask_20 = _mm512_set1_epi8(0x20);
74:   const __m512i mask_30 = _mm512_set1_epi8(0x30);
75:   const __m512i mask_80 = _mm512_set1_epi8(static_cast<char>(0x80));
76:   const __m512i mask_c0 = _mm512_set1_epi8(static_cast<char>(0xC0));
77:   const __m512i mask_e0 = _mm512_set1_epi8(static_cast<char>(0xE0));
78:   const __m512i mask_f0 = _mm512_set1_epi8(static_cast<char>(0xF0));
79:   const __m512i mask_f4 = _mm512_set1_epi8(static_cast<char>(0xF4));
80:   const __m512i mask_f8 = _mm512_set1_epi8(static_cast<char>(0xF8));
81: 
82:   // Probe four complete blocks at once; the scalar validator still handles the tail.
83:   while (pending == 0 && length - offset >= 256) {
84:     const __m512i block0 = _mm512_loadu_si512(
85:         reinterpret_cast<const void *>(bytes + offset));
86:     const __m512i block1 = _mm512_loadu_si512(
87:         reinterpret_cast<const void *>(bytes + offset + 64));
88:     const __m512i block2 = _mm512_loadu_si512(
89:         reinterpret_cast<const void *>(bytes + offset + 128));
90:     const __m512i block3 = _mm512_loadu_si512(
91:         reinterpret_cast<const void *>(bytes + offset + 192));
92:     const __mmask64 ascii0 = _mm512_cmpeq_epi8_mask(
93:         _mm512_and_si512(block0, mask_80), zero);
94:     const __mmask64 ascii1 = _mm512_cmpeq_epi8_mask(
95:         _mm512_and_si512(block1, mask_80), zero);
96:     const __mmask64 ascii2 = _mm512_cmpeq_epi8_mask(
97:         _mm512_and_si512(block2, mask_80), zero);
98:     const __mmask64 ascii3 = _mm512_cmpeq_epi8_mask(
99:         _mm512_and_si512(block3, mask_80), zero);
100: 
101:     if ((ascii0 & ascii1 & ascii2 & ascii3) != UINT64_MAX) {
102:       break;
103:     }
104:     offset += 256;
105:   }
106: 
107:   // The current load requires 64 bytes; the shifted load requires 65.
108:   // Any unprocessed tail is validated by the scalar path below.
109:   while (length - offset >= 64) {
110:     const __m512i current = _mm512_loadu_si512(
111:         reinterpret_cast<const void *>(bytes + offset));
112:     const __mmask64 ascii = _mm512_cmpeq_epi8_mask(
113:         _mm512_and_si512(current, mask_80), zero);
114: 
115:     if (length - offset < 65) {
116:       break;
117:     }
118: 
119:     const __m512i next1 = _mm512_loadu_si512(
120:         reinterpret_cast<const void *>(bytes + offset + 1));
121:     const __mmask64 continuation = _mm512_cmpeq_epi8_mask(
122:         _mm512_and_si512(current, mask_c0), mask_80);
123:     const __mmask64 lead2 =
124:         _mm512_cmpeq_epi8_mask(_mm512_and_si512(current, mask_e0), mask_c0) &
125:         _mm512_cmpgt_epi8_mask(_mm512_and_si512(current, mask_1f), one);
126:     const __mmask64 lead3 = _mm512_cmpeq_epi8_mask(
127:         _mm512_and_si512(current, mask_f0), mask_e0);
128:     const __mmask64 high4 = _mm512_cmpeq_epi8_mask(
129:         _mm512_and_si512(current, mask_f8), mask_f0);
130:     const __mmask64 invalid4_low = _mm512_cmpgt_epi8_mask(
131:         _mm512_and_si512(current, mask_07), _mm512_set1_epi8(4));
132:     const __mmask64 lead4 = high4 & ~invalid4_low;
133:     const __mmask64 valid = ascii | continuation | lead2 | lead3 | lead4;
134: 
135:     if (valid != UINT64_MAX) {
136:       return false;
137:     }
138: 
139:     const __mmask64 e0 = _mm512_cmpeq_epi8_mask(
140:         current, _mm512_set1_epi8(static_cast<char>(0xE0)));
141:     const __mmask64 ed = _mm512_cmpeq_epi8_mask(
142:         current, _mm512_set1_epi8(static_cast<char>(0xED)));
143:     const __mmask64 f0 = _mm512_cmpeq_epi8_mask(
144:         current, _mm512_set1_epi8(static_cast<char>(0xF0)));
145:     const __mmask64 f4 = _mm512_cmpeq_epi8_mask(current, mask_f4);
146: 
147:     const __m512i second_bit5 = _mm512_and_si512(next1, mask_20);
148:     const __mmask64 bad_e0 = e0 & _mm512_cmpeq_epi8_mask(second_bit5, zero);
149:     const __mmask64 bad_ed =
150:         ed & _mm512_cmpeq_epi8_mask(second_bit5, mask_20);
151:     const __mmask64 bad_f0 = f0 & _mm512_cmpeq_epi8_mask(
152:         _mm512_and_si512(next1, mask_f0), mask_80);
153:     const __mmask64 bad_f4 = f4 & ~_mm512_cmpeq_epi8_mask(
154:         _mm512_and_si512(next1, mask_30), zero);
155:     if ((bad_e0 | bad_ed | bad_f0 | bad_f4) != 0) {
156:       return false;
157:     }
158: 
159:     const uint64_t lead2_bits = static_cast<uint64_t>(lead2);
160:     const uint64_t lead3_bits = static_cast<uint64_t>(lead3);
161:     const uint64_t lead4_bits = static_cast<uint64_t>(lead4);
162:     const uint64_t expected =
163:         (lead2_bits << 1) |
164:         (lead3_bits << 1) | (lead3_bits << 2) |
165:         (lead4_bits << 1) | (lead4_bits << 2) | (lead4_bits << 3);
166:     const uint64_t expected_next =
167:         (lead2_bits >> 63) |
168:         (lead3_bits >> 63) | (lead3_bits >> 62) |
169:         (lead4_bits >> 63) | (lead4_bits >> 62) | (lead4_bits >> 61);
170:     const uint64_t continuation_bits =
171:         static_cast<uint64_t>(continuation);
172:     if (continuation_bits != (expected | pending)) {
173:       return false;
174:     }
175: 
176:     pending = expected_next;
177:     offset += 64;
178:   }
179: 
180:   return validate_utf8_scalar(bytes, length, offset,
181:                               static_cast<uint32_t>(pending));
182: }
183: #endif
