92:       continue;
93:     }
94: 
95:     if (length - offset < 65) {
96:       break;
97:     }
98: 
99:     const __m512i next1 = _mm512_loadu_si512(
100:         reinterpret_cast<const void *>(bytes + offset + 1));
101:     const __mmask64 continuation = _mm512_cmpeq_epi8_mask(
102:         _mm512_and_si512(current, mask_c0), mask_80);
103:     const __mmask64 lead2 =
104:         _mm512_cmpeq_epi8_mask(_mm512_and_si512(current, mask_e0), mask_c0) &
105:         _mm512_cmpgt_epi8_mask(_mm512_and_si512(current, mask_1f), one);
106:     const __mmask64 lead3 = _mm512_cmpeq_epi8_mask(
107:         _mm512_and_si512(current, mask_f0), mask_e0);
108:     const __mmask64 high4 = _mm512_cmpeq_epi8_mask(
109:         _mm512_and_si512(current, mask_f8), mask_f0);
110:     const __mmask64 invalid4_low = _mm512_cmpgt_epi8_mask(
111:         _mm512_and_si512(current, mask_07), _mm512_set1_epi8(4));
