113:     const __mmask64 valid = ascii | continuation | lead2 | lead3 | lead4;
114: 
115:     if (valid != UINT64_MAX) {
116:       return false;
117:     }
118: 
119:     const __mmask64 e0 = _mm512_cmpeq_epi8_mask(
120:         current, _mm512_set1_epi8(static_cast<char>(0xE0)));
121:     const __mmask64 ed = _mm512_cmpeq_epi8_mask(
122:         current, _mm512_set1_epi8(static_cast<char>(0xED)));
123:     const __mmask64 f0 = _mm512_cmpeq_epi8_mask(
124:         current, _mm512_set1_epi8(static_cast<char>(0xF0)));
125:     const __mmask64 f4 = _mm512_cmpeq_epi8_mask(current, mask_f4);
126: 
127:     const __m512i second_bit5 = _mm512_and_si512(next1, mask_20);
128:     const __mmask64 bad_e0 = e0 & _mm512_cmpeq_epi8_mask(second_bit5, zero);
