139:     const uint64_t lead2_bits = static_cast<uint64_t>(lead2);
140:     const uint64_t lead3_bits = static_cast<uint64_t>(lead3);
141:     const uint64_t lead4_bits = static_cast<uint64_t>(lead4);
142:     const uint64_t expected =
143:         (lead2_bits << 1) |
144:         (lead3_bits << 1) | (lead3_bits << 2) |
145:         (lead4_bits << 1) | (lead4_bits << 2) | (lead4_bits << 3);
146:     const uint64_t expected_next =
147:         (lead2_bits >> 63) |
148:         (lead3_bits >> 63) | (lead3_bits >> 62) |
149:         (lead4_bits >> 63) | (lead4_bits >> 62) | (lead4_bits >> 61);
150:     const uint64_t continuation_bits =
151:         static_cast<uint64_t>(continuation);
152:     if (continuation_bits != (expected | pending)) {
153:       return false;
154:     }
155: 
156:     pending = expected_next;
157:     offset += 64;
158:   }
159: 
160:   return validate_utf8_scalar(bytes, length, offset,
161:                               static_cast<uint32_t>(pending));
162: }
163: #endif
