11:         return true;
12:       }
13:       byte1 = bytes[index++];
14:     } while (byte1 < 0x80);
15:     if (byte1 < 0xE0) {
16:       // Two-byte form.
17:       if (index == length) {
18:         return false;
19:       }
20:       if (byte1 < 0xC2 || (bytes[index++] & 0xC0) != 0x80) {
21:         return false;
22:       }
23:     } else if (byte1 < 0xF0) {
24:       // Three-byte form.
25:       if (index + 1 >= length) {
26:         return false;
27:       }
28:       unsigned char byte2 = bytes[index++];
29:       if ((byte2 & 0xC0) != 0x80
30:           // Overlong? 5 most significant bits must not all be zero.
