34:           // Third byte trailing-byte test.
35:           || (bytes[index++] & 0xC0) != 0x80) {
36:         return false;
37:       }
38:     } else {
39: 
40:       // Four-byte form.
41:       if (index + 2 >= length) {
42:         return false;
43:       }
44:       int byte2 = bytes[index++];
45:       if ((byte2 & 0xC0) != 0x80
46:           // Check that 1 <= plane <= 16. Tricky optimized form of:
47:           // if (byte1 > (byte) 0xF4
48:           //     || byte1 == (byte) 0xF0 && byte2 < (byte) 0x90
49:           //     || byte1 == (byte) 0xF4 && byte2 > (byte) 0x8F)
50:           || (byte1 > 0xF4 || (byte1 == 0xF0 && byte2 < 0x90) || (byte1 == 0xF4 && byte2 > 0x8F))
51:           // Third byte trailing-byte test
52:           || (bytes[index++] & 0xC0) != 0x80
53:           // Fourth byte trailing-byte test
54:           || (bytes[index++] & 0xC0) != 0x80) {
55:         return false;
56:       }
57:     }
58:   }
59: }
