64: #if UTF8_HAS_AVX512BW_TARGET
65: __attribute__((target("avx512f,avx512bw"), always_inline))
66: static inline bool validate_utf8_avx512_block(__m512i current,
67:                                              __m512i next1,
68:                                              uint32_t &pending) {
69:   const __m512i zero = _mm512_setzero_si512();
70:   const __m512i one = _mm512_set1_epi8(1);
71:   const __m512i four = _mm512_set1_epi8(4);
72:   const __m512i mask_07 = _mm512_set1_epi8(7);
73:   const __m512i mask_1f = _mm512_set1_epi8(0x1F);
74:   const __m512i mask_20 = _mm512_set1_epi8(0x20);
75:   const __m512i mask_30 = _mm512_set1_epi8(0x30);
76:   const __m512i mask_80 = _mm512_set1_epi8(static_cast<char>(0x80));
77:   const __m512i mask_c0 = _mm512_set1_epi8(static_cast<char>(0xC0));
78:   const __m512i mask_e0 = _mm512_set1_epi8(static_cast<char>(0xE0));
79:   const __m512i mask_f0 = _mm512_set1_epi8(static_cast<char>(0xF0));
80:   const __m512i mask_f4 = _mm512_set1_epi8(static_cast<char>(0xF4));
81:   const __m512i mask_f8 = _mm512_set1_epi8(static_cast<char>(0xF8));
82: 
83:   const __mmask64 ascii = _mm512_cmpeq_epi8_mask(
84:       _mm512_and_si512(current, mask_80), zero);
85:   const __mmask64 continuation = _mm512_cmpeq_epi8_mask(
86:       _mm512_and_si512(current, mask_c0), mask_80);
87:   const __mmask64 lead2 =
88:       _mm512_cmpeq_epi8_mask(_mm512_and_si512(current, mask_e0), mask_c0) &
89:       _mm512_cmpgt_epi8_mask(_mm512_and_si512(current, mask_1f), one);
90:   const __mmask64 lead3 = _mm512_cmpeq_epi8_mask(
91:       _mm512_and_si512(current, mask_f0), mask_e0);
92:   const __mmask64 high4 = _mm512_cmpeq_epi8_mask(
93:       _mm512_and_si512(current, mask_f8), mask_f0);
94:   const __mmask64 invalid4_low = _mm512_cmpgt_epi8_mask(
95:       _mm512_and_si512(current, mask_07), four);
96:   const __mmask64 lead4 = high4 & ~invalid4_low;
97: 
98:   if ((ascii | continuation | lead2 | lead3 | lead4) !=
99:       ~static_cast<__mmask64>(0)) {
100:     return false;
101:   }
102: 
103:   const __mmask64 e0 = _mm512_cmpeq_epi8_mask(
104:       current, _mm512_set1_epi8(static_cast<char>(0xE0)));
105:   const __mmask64 ed = _mm512_cmpeq_epi8_mask(
106:       current, _mm512_set1_epi8(static_cast<char>(0xED)));
107:   const __mmask64 f0 = _mm512_cmpeq_epi8_mask(
108:       current, _mm512_set1_epi8(static_cast<char>(0xF0)));
109:   const __mmask64 f4 = _mm512_cmpeq_epi8_mask(current, mask_f4);
110: 
111:   const __mmask64 bad_e0 = e0 & _mm512_cmpeq_epi8_mask(
112:       _mm512_and_si512(next1, mask_20), zero);
113:   const __mmask64 bad_ed = ed & _mm512_cmpeq_epi8_mask(
114:       _mm512_and_si512(next1, mask_20), mask_20);
115:   const __mmask64 bad_f0 = f0 & _mm512_cmpeq_epi8_mask(
116:       _mm512_and_si512(next1, mask_f0), mask_80);
117:   const __mmask64 bad_f4 = f4 & ~_mm512_cmpeq_epi8_mask(
118:       _mm512_and_si512(next1, mask_30), zero);
119:   if ((bad_e0 | bad_ed | bad_f0 | bad_f4) != 0) {
120:     return false;
121:   }
122: 
123:   const uint64_t lead2_bits = static_cast<uint64_t>(lead2);
124:   const uint64_t lead3_bits = static_cast<uint64_t>(lead3);
125:   const uint64_t lead4_bits = static_cast<uint64_t>(lead4);
126:   const uint64_t expected =
127:       (lead2_bits << 1) |
128:       (lead3_bits << 1) | (lead3_bits << 2) |
129:       (lead4_bits << 1) | (lead4_bits << 2) | (lead4_bits << 3);
130:   const uint64_t continuation_bits = static_cast<uint64_t>(continuation);
131:   if (continuation_bits != (expected | static_cast<uint64_t>(pending))) {
132:     return false;
133:   }
134: 
135:   // Carry the expected continuation positions beyond lane 63 into the next block.
136:   pending = static_cast<uint32_t>(
137:       ((lead2_bits >> 63) & 1u) |
138:       ((lead3_bits >> 62) & 1u) |
139:       (((lead3_bits >> 63) & 1u) * 3u) |
140:       ((lead4_bits >> 61) & 1u) |
141:       (((lead4_bits >> 62) & 1u) * 3u) |
142:       (((lead4_bits >> 63) & 1u) * 7u));
143:   return true;
144: }
