10: static bool validate_utf8(const char *b, size_t length) {
11:   const unsigned char *bytes = (const unsigned char *)b;
12:   for (size_t index = 0;;) {
13:     if (index == length) {
14:       return true;
15:     }
16: 
17:     // Avoid a word load when the next byte already begins a multibyte sequence.
18:     if (bytes[index] < 0x80) {
19:       while (length - index >= sizeof(uint64_t)) {
20:         uint64_t word;
21:         std::memcpy(&word, bytes + index, sizeof(word));
22:         if ((word & UINT64_C(0x8080808080808080)) != 0) {
23:           break;
24:         }
25:         index += sizeof(word);
26:       }
27:       while (index < length && bytes[index] < 0x80) {
28:         ++index;
29:       }
30:       if (index == length) {
31:         return true;
32:       }
33:     }
34: 
35:     unsigned char byte1 = bytes[index++];
36:     if (byte1 < 0xE0) {
37:       // Two-byte form.
38:       if (index == length) {
39:         return false;
40:       }
41:       if (byte1 < 0xC2 || (bytes[index++] & 0xC0) != 0x80) {
42:         return false;
43:       }
44:     } else if (byte1 < 0xF0) {
45:       // Three-byte form.
46:       if (index + 1 >= length) {
47:         return false;
48:       }
49:       unsigned char byte2 = bytes[index++];
50:       if ((byte2 & 0xC0) != 0x80
51:           // Overlong? 5 most significant bits must not all be zero.
52:           || (byte1 == 0xE0 && byte2 < 0xA0)
53:           // Check for illegal surrogate codepoints.
54:           || (byte1 == 0xED && 0xA0 <= byte2)
55:           // Third byte trailing-byte test.
56:           || (bytes[index++] & 0xC0) != 0x80) {
57:         return false;
58:       }
59:     } else {
60:       // Four-byte form.
61:       if (index + 2 >= length) {
62:         return false;
63:       }
64:       int byte2 = bytes[index++];
65:       if ((byte2 & 0xC0) != 0x80
66:           // Check that 1 <= plane <= 16. Tricky optimized form of:
67:           // if (byte1 > (byte) 0xF4
68:           //     || byte1 == (byte) 0xF0 && byte2 < (byte) 0x90
69:           //     || byte1 == (byte) 0xF4 && byte2 > (byte) 0x8F)
70:           || (byte1 > 0xF4 || (byte1 == 0xF0 && byte2 < 0x90) || (byte1 == 0xF4 && byte2 > 0x8F))
71:           // Third byte trailing-byte test
72:           || (bytes[index++] & 0xC0) != 0x80
73:           // Fourth byte trailing-byte test
74:           || (bytes[index++] & 0xC0) != 0x80) {
75:         return false;
76:       }
77:     }
78:   }
79: }
