67:   const __m256i four = _mm256_set1_epi8(4);
68:   const __m256i mask_07 = _mm256_set1_epi8(7);
69:   const __m256i mask_1f = _mm256_set1_epi8(0x1F);
70:   const __m256i mask_20 = _mm256_set1_epi8(0x20);
71:   const __m256i mask_30 = _mm256_set1_epi8(0x30);
72:   const __m256i mask_80 = _mm256_set1_epi8(static_cast<char>(0x80));
73:   const __m256i mask_c0 = _mm256_set1_epi8(static_cast<char>(0xC0));
74:   const __m256i mask_e0 = _mm256_set1_epi8(static_cast<char>(0xE0));
75:   const __m256i mask_f0 = _mm256_set1_epi8(static_cast<char>(0xF0));
76:   const __m256i mask_f8 = _mm256_set1_epi8(static_cast<char>(0xF8));
77:   const __m256i mask_f4 = _mm256_set1_epi8(static_cast<char>(0xF4));
78: 
79:   const __m256i current = _mm256_loadu_si256(
80:       reinterpret_cast<const __m256i *>(bytes + offset));
81:   const __m256i next1 = _mm256_loadu_si256(
82:       reinterpret_cast<const __m256i *>(bytes + offset + 1));
83: 
84:   const __m256i ascii = _mm256_cmpeq_epi8(
85:       _mm256_and_si256(current, mask_80), zero);
86:   const __m256i continuation = _mm256_cmpeq_epi8(
87:       _mm256_and_si256(current, mask_c0), mask_80);
88:   const __m256i lead2 = _mm256_and_si256(
89:       _mm256_cmpeq_epi8(_mm256_and_si256(current, mask_e0), mask_c0),
90:       _mm256_cmpgt_epi8(_mm256_and_si256(current, mask_1f), one));
91:   const __m256i lead3 = _mm256_cmpeq_epi8(
92:       _mm256_and_si256(current, mask_f0), mask_e0);
93:   const __m256i high4 = _mm256_cmpeq_epi8(
94:       _mm256_and_si256(current, mask_f8), mask_f0);
95:   const __m256i invalid4_low = _mm256_cmpgt_epi8(
96:       _mm256_and_si256(current, mask_07), four);
97:   const __m256i lead4 = _mm256_andnot_si256(invalid4_low, high4);
98:   const __m256i valid = _mm256_or_si256(
99:       _mm256_or_si256(ascii, continuation),
100:       _mm256_or_si256(lead2, _mm256_or_si256(lead3, lead4)));
