102:   if (_mm256_movemask_epi8(valid) != -1) {
103:     return false;
104:   }
105: 
106:   const __m256i e0 = _mm256_cmpeq_epi8(
107:       current, _mm256_set1_epi8(static_cast<char>(0xE0)));
108:   const __m256i ed = _mm256_cmpeq_epi8(
109:       current, _mm256_set1_epi8(static_cast<char>(0xED)));
110:   const __m256i f0 = _mm256_cmpeq_epi8(
111:       current, _mm256_set1_epi8(static_cast<char>(0xF0)));
112:   const __m256i f4 = _mm256_cmpeq_epi8(current, mask_f4);
113: 
114:   const __m256i second_bit5 = _mm256_and_si256(next1, mask_20);
115:   const __m256i bad_e0 = _mm256_and_si256(
116:       e0, _mm256_cmpeq_epi8(second_bit5, zero));
117:   const __m256i bad_ed = _mm256_and_si256(
118:       ed, _mm256_cmpeq_epi8(second_bit5, mask_20));
119:   const __m256i bad_f0 = _mm256_and_si256(
120:       f0, _mm256_cmpeq_epi8(_mm256_and_si256(next1, mask_f0), mask_80));
121:   const __m256i bad_f4 = _mm256_andnot_si256(
122:       _mm256_cmpeq_epi8(_mm256_and_si256(next1, mask_30), zero), f4);
123:   const __m256i bad_second = _mm256_or_si256(
124:       _mm256_or_si256(bad_e0, bad_ed), _mm256_or_si256(bad_f0, bad_f4));
125:   if (_mm256_movemask_epi8(bad_second) != 0) {
126:     return false;
127:   }
