133:   const uint32_t lead4_bits =
134:       static_cast<uint32_t>(_mm256_movemask_epi8(lead4));
135:   const uint64_t expected =
136:       (static_cast<uint64_t>(lead2_bits) << 1) |
137:       (static_cast<uint64_t>(lead3_bits) << 1) |
138:       (static_cast<uint64_t>(lead3_bits) << 2) |
139:       (static_cast<uint64_t>(lead4_bits) << 1) |
140:       (static_cast<uint64_t>(lead4_bits) << 2) |
