154: static bool validate_utf8_avx2(const unsigned char *bytes, size_t length) {
155:   size_t offset = 0;
156:   uint32_t pending = 0;
157: 
158:   // Each pair is two complete 32-byte blocks; the second shifted load needs
159:   // bytes through offset + 64, hence the 65-byte guard.
160:   while (length - offset >= 65) {
161:     if (!validate_utf8_avx2_block(bytes, offset, &pending) ||
162:         !validate_utf8_avx2_block(bytes, offset + 32, &pending)) {
163:       return false;
164:     }
165:     offset += 64;
166:   }
167: 
168:   // Process one complete block at a time, leaving at most 32 bytes for scalar.
169:   while (length - offset >= 33) {
170:     if (!validate_utf8_avx2_block(bytes, offset, &pending)) {
171:       return false;
172:     }
173:     offset += 32;
174:   }
175: 
176:   return validate_utf8_scalar(bytes, length, offset, pending);
177: }
