64: #if UTF8_HAS_AVX512_TARGET
65: __attribute__((target("avx512f,avx512bw")))
66: static bool validate_utf8_avx512(const unsigned char *bytes, size_t length) {
67:   size_t offset = 0;
68:   uint32_t pending = 0;
69:   const __m512i zero = _mm512_setzero_si512();
70:   const __m512i mask_80 = _mm512_set1_epi8(static_cast<char>(0x80));
71:   const __m512i mask_c0 = _mm512_set1_epi8(static_cast<char>(0xC0));
72:   const __m512i mask_f0 = _mm512_set1_epi8(static_cast<char>(0xF0));
73:   const __m512i mask_f8 = _mm512_set1_epi8(static_cast<char>(0xF8));
74:   const __m512i value_80 = _mm512_set1_epi8(static_cast<char>(0x80));
75:   const __m512i value_c2 = _mm512_set1_epi8(static_cast<char>(0xC2));
76:   const __m512i value_e0 = _mm512_set1_epi8(static_cast<char>(0xE0));
77:   const __m512i value_f0 = _mm512_set1_epi8(static_cast<char>(0xF0));
78:   const __m512i value_f5 = _mm512_set1_epi8(static_cast<char>(0xF5));
79:   const __m512i value_a0 = _mm512_set1_epi8(static_cast<char>(0xA0));
80:   const __m512i value_90 = _mm512_set1_epi8(static_cast<char>(0x90));
81:   const __m512i value_8f = _mm512_set1_epi8(static_cast<char>(0x8F));
82:   const __m512i value_e0_byte = _mm512_set1_epi8(static_cast<char>(0xE0));
83:   const __m512i value_ed_byte = _mm512_set1_epi8(static_cast<char>(0xED));
84:   const __m512i value_f4_byte = _mm512_set1_epi8(static_cast<char>(0xF4));
85: 
86:   // The shifted load reads through offset + 64, so 65 remaining bytes are
87:   // required. The final at-most-64 bytes are checked by the scalar validator.
88:   while (length - offset >= 65) {
89:     const __m512i current = _mm512_loadu_si512(
90:         reinterpret_cast<const void *>(bytes + offset));
91:     const __mmask64 ascii_only = _mm512_cmp_epu8_mask(
92:         current, value_80, _MM_CMPINT_LT);
93: 
94:     // ASCII blocks need no look-ahead or continuation bookkeeping.
95:     if (pending == 0 && ascii_only == static_cast<__mmask64>(UINT64_MAX)) {
96:       offset += 64;
97:       continue;
98:     }
99: 
100:     const __m512i next1 = _mm512_loadu_si512(
101:         reinterpret_cast<const void *>(bytes + offset + 1));
102: 
103:     const __mmask64 ascii = ascii_only;
104:     const __mmask64 continuation = _mm512_cmpeq_epi8_mask(
105:         _mm512_and_si512(current, mask_c0), mask_80);
106:     const __mmask64 lead2 =
107:         _mm512_cmp_epu8_mask(current, value_c2, _MM_CMPINT_GE) &
108:         _mm512_cmp_epu8_mask(current, value_e0, _MM_CMPINT_LT);
109:     const __mmask64 lead3 = _mm512_cmpeq_epi8_mask(
110:         _mm512_and_si512(current, mask_f0), value_e0);
111:     const __mmask64 lead4 =
112:         _mm512_cmp_epu8_mask(current, value_f0, _MM_CMPINT_GE) &
113:         _mm512_cmp_epu8_mask(current, value_f5, _MM_CMPINT_LT);
114:     const __mmask64 valid = ascii | continuation | lead2 | lead3 | lead4;
115:     if (valid != static_cast<__mmask64>(UINT64_MAX)) {
116:       return false;
117:     }
118: 
119:     const __mmask64 lead_e0 =
120:         _mm512_cmpeq_epi8_mask(current, value_e0_byte);
121:     const __mmask64 lead_ed =
122:         _mm512_cmpeq_epi8_mask(current, value_ed_byte);
123:     const __mmask64 lead_f0 =
124:         _mm512_cmpeq_epi8_mask(current, value_f0);
125:     const __mmask64 lead_f4 =
126:         _mm512_cmpeq_epi8_mask(current, value_f4_byte);
127:     const __mmask64 bad_e0 =
128:         lead_e0 & _mm512_cmp_epu8_mask(next1, value_a0, _MM_CMPINT_LT);
129:     const __mmask64 bad_ed =
130:         lead_ed & _mm512_cmp_epu8_mask(next1, value_a0, _MM_CMPINT_GE);
131:     const __mmask64 bad_f0 =
132:         lead_f0 & _mm512_cmp_epu8_mask(next1, value_90, _MM_CMPINT_LT);
133:     const __mmask64 bad_f4 =
134:         lead_f4 & _mm512_cmp_epu8_mask(next1, value_8f, _MM_CMPINT_GT);
135:     if ((bad_e0 | bad_ed | bad_f0 | bad_f4) != 0) {
136:       return false;
137:     }
138: 
139:     const uint64_t lead2_bits = static_cast<uint64_t>(lead2);
140:     const uint64_t lead3_bits = static_cast<uint64_t>(lead3);
141:     const uint64_t lead4_bits = static_cast<uint64_t>(lead4);
142:     const uint64_t expected =
143:         (lead2_bits << 1) | (lead3_bits << 1) | (lead3_bits << 2) |
144:         (lead4_bits << 1) | (lead4_bits << 2) | (lead4_bits << 3);
145:     const uint64_t continuation_bits =
146:         static_cast<uint64_t>(continuation);
147:     if (continuation_bits != (expected | static_cast<uint64_t>(pending))) {
148:       return false;
149:     }
150: 
151:     const uint32_t pending0 = static_cast<uint32_t>(
152:         ((lead2_bits >> 63) & 1u) | ((lead3_bits >> 62) & 1u) |
153:         ((lead3_bits >> 63) & 1u) | ((lead4_bits >> 61) & 1u) |
154:         ((lead4_bits >> 62) & 1u) | ((lead4_bits >> 63) & 1u));
155:     const uint32_t pending1 = static_cast<uint32_t>(
156:         ((lead3_bits >> 63) & 1u) | ((lead4_bits >> 62) & 1u) |
157:         ((lead4_bits >> 63) & 1u));
158:     const uint32_t pending2 =
159:         static_cast<uint32_t>((lead4_bits >> 63) & 1u);
160:     pending = pending0 | (pending1 << 1) | (pending2 << 2);
161:     offset += 64;
162:   }
163: 
164:   return validate_utf8_scalar(bytes, length, offset, pending);
165: }
166: #endif
167: 
168: static bool validate_utf8(const char *input, size_t length) {
169:   const unsigned char *bytes = reinterpret_cast<const unsigned char *>(input);
170: #if UTF8_HAS_AVX512_TARGET
171:   if (length >= 65) {
172:     return validate_utf8_avx512(bytes, length);
173:   }
174: #endif
175:   return validate_utf8_scalar(bytes, length, 0, 0);
176: }
177: 
178: extern "C" void run(const void *input1, const void *input2, void *output,
179:                     int n, int parameter, int threads) {
180:   *(uint32_t *)output = validate_utf8((const char *)input1, n);
181: }

