77:   const __m256i mask_c0 = _mm256_set1_epi8(static_cast<char>(0xC0));
78:   const __m256i mask_e0 = _mm256_set1_epi8(static_cast<char>(0xE0));
79:   const __m256i mask_f0 = _mm256_set1_epi8(static_cast<char>(0xF0));
80:   const __m256i mask_f8 = _mm256_set1_epi8(static_cast<char>(0xF8));
81:   const __m256i mask_f4 = _mm256_set1_epi8(static_cast<char>(0xF4));
