96:         _mm256_cmpeq_epi8(_mm256_and_si256(current, mask_e0), mask_c0),
97:         _mm256_cmpgt_epi8(_mm256_and_si256(current, mask_1f), one));
98:     const __m256i lead3 = _mm256_cmpeq_epi8(
99:         _mm256_and_si256(current, mask_f0), mask_e0);
100:     const __m256i high4 = _mm256_cmpeq_epi8(
101:         _mm256_and_si256(current, mask_f8), mask_f0);
102:     const __m256i invalid4_low = _mm256_cmpgt_epi8(
103:         _mm256_and_si256(current, mask_07), four);
104:     const __m256i lead4 = _mm256_andnot_si256(invalid4_low, high4);
