17: static bool validate_utf8_scalar(const unsigned char *bytes, size_t length,
18:                                  size_t index, uint32_t pending) {
19:   while (pending != 0) {
20:     if (index >= length || (bytes[index++] & 0xC0u) != 0x80u) {
21:       return false;
22:     }
23:     pending >>= 1;
24:   }
25: 
26:   while (index < length) {
27:     const unsigned char byte1 = bytes[index++];
28:     if (byte1 < 0x80) {
29:       continue;
30:     }
31:     if (byte1 < 0xE0) {
32:       if (byte1 < 0xC2 || index >= length ||
33:           (bytes[index++] & 0xC0u) != 0x80u) {
34:         return false;
35:       }
36:     } else if (byte1 < 0xF0) {
37:       if (length - index < 2) {
38:         return false;
39:       }
40:       const unsigned char byte2 = bytes[index++];
41:       if ((byte2 & 0xC0u) != 0x80u ||
42:           (byte1 == 0xE0 && byte2 < 0xA0) ||
43:           (byte1 == 0xED && byte2 >= 0xA0) ||
44:           (bytes[index++] & 0xC0u) != 0x80u) {
45:         return false;
46:       }
47:     } else {
48:       if (length - index < 3) {
49:         return false;
50:       }
51:       const unsigned char byte2 = bytes[index++];
52:       if ((byte2 & 0xC0u) != 0x80u || byte1 > 0xF4 ||
53:           (byte1 == 0xF0 && byte2 < 0x90) ||
54:           (byte1 == 0xF4 && byte2 > 0x8F) ||
55:           (bytes[index++] & 0xC0u) != 0x80u ||
56:           (bytes[index++] & 0xC0u) != 0x80u) {
57:         return false;
58:       }
59:     }
60:   }
61:   return true;
62: }
63: 
64: #if UTF8_HAS_AVX512_TARGET
65: __attribute__((target("avx512f,avx512bw")))
66: static bool validate_utf8_avx512(const unsigned char *bytes, size_t length) {
67:   size_t offset = 0;
68:   uint64_t pending = 0;
69:   const __m512i zero = _mm512_setzero_si512();
70:   const __m512i one = _mm512_set1_epi8(1);
71:   const __m512i four = _mm512_set1_epi8(4);
72:   const __m512i mask_07 = _mm512_set1_epi8(7);
73:   const __m512i mask_1f = _mm512_set1_epi8(0x1F);
74:   const __m512i mask_20 = _mm512_set1_epi8(0x20);
75:   const __m512i mask_30 = _mm512_set1_epi8(0x30);
76:   const __m512i mask_80 = _mm512_set1_epi8(static_cast<char>(0x80));
77:   const __m512i mask_c0 = _mm512_set1_epi8(static_cast<char>(0xC0));
78:   const __m512i mask_e0 = _mm512_set1_epi8(static_cast<char>(0xE0));
79:   const __m512i mask_f0 = _mm512_set1_epi8(static_cast<char>(0xF0));
80:   const __m512i mask_f8 = _mm512_set1_epi8(static_cast<char>(0xF8));
81:   const __m512i mask_f4 = _mm512_set1_epi8(static_cast<char>(0xF4));
82:   const __mmask64 first_63_lanes =
83:       static_cast<__mmask64>(UINT64_MAX >> 1);
84: 
85:   // A shifted vector is loaded only when all 64 bytes are in bounds.
86:   // For the final full block, mask off its out-of-range 64th shifted byte.
87:   while (length - offset >= 64) {
88:     const size_t remaining = length - offset;
89:     const __m512i current = _mm512_loadu_si512(
90:         reinterpret_cast<const void *>(bytes + offset));
91:     const __m512i next1 = remaining > 64
92:         ? _mm512_loadu_si512(
93:               reinterpret_cast<const void *>(bytes + offset + 1))
94:         : _mm512_maskz_loadu_epi8(
95:               first_63_lanes,
96:               reinterpret_cast<const void *>(bytes + offset + 1));
97: 
98:     const __mmask64 ascii = _mm512_cmpeq_epi8_mask(
99:         _mm512_and_si512(current, mask_80), zero);
100:     const __mmask64 continuation = _mm512_cmpeq_epi8_mask(
101:         _mm512_and_si512(current, mask_c0), mask_80);
102:     const __mmask64 lead2 =
103:         _mm512_cmpeq_epi8_mask(_mm512_and_si512(current, mask_e0), mask_c0) &
104:         _mm512_cmpgt_epi8_mask(_mm512_and_si512(current, mask_1f), one);
105:     const __mmask64 lead3 = _mm512_cmpeq_epi8_mask(
106:         _mm512_and_si512(current, mask_f0), mask_e0);
107:     const __mmask64 high4 = _mm512_cmpeq_epi8_mask(
108:         _mm512_and_si512(current, mask_f8), mask_f0);
109:     const __mmask64 invalid4_low = _mm512_cmpgt_epi8_mask(
110:         _mm512_and_si512(current, mask_07), four);
111:     const __mmask64 lead4 = high4 & ~invalid4_low;
112:     const __mmask64 valid = ascii | continuation | lead2 | lead3 | lead4;
113: 
114:     if (valid != static_cast<__mmask64>(UINT64_MAX)) {
115:       return false;
116:     }
117: 
118:     const __mmask64 e0 = _mm512_cmpeq_epi8_mask(
119:         current, _mm512_set1_epi8(static_cast<char>(0xE0)));
120:     const __mmask64 ed = _mm512_cmpeq_epi8_mask(
121:         current, _mm512_set1_epi8(static_cast<char>(0xED)));
122:     const __mmask64 f0 = _mm512_cmpeq_epi8_mask(
123:         current, _mm512_set1_epi8(static_cast<char>(0xF0)));
124:     const __mmask64 f4 = _mm512_cmpeq_epi8_mask(current, mask_f4);
125: 
126:     const __m512i second_bit5 = _mm512_and_si512(next1, mask_20);
127:     const __mmask64 bad_e0 = e0 & _mm512_cmpeq_epi8_mask(second_bit5, zero);
128:     const __mmask64 bad_ed = ed & _mm512_cmpeq_epi8_mask(second_bit5, mask_20);
129:     const __mmask64 bad_f0 = f0 & _mm512_cmpeq_epi8_mask(
130:         _mm512_and_si512(next1, mask_f0), mask_80);
131:     const __mmask64 bad_f4 = f4 & ~_mm512_cmpeq_epi8_mask(
132:         _mm512_and_si512(next1, mask_30), zero);
133:     if ((bad_e0 | bad_ed | bad_f0 | bad_f4) != 0) {
134:       return false;
135:     }
136: 
137:     const uint64_t lead2_bits = static_cast<uint64_t>(lead2);
138:     const uint64_t lead3_bits = static_cast<uint64_t>(lead3);
139:     const uint64_t lead4_bits = static_cast<uint64_t>(lead4);
140:     const uint64_t expected =
141:         (lead2_bits << 1) |
142:         (lead3_bits << 1) | (lead3_bits << 2) |
143:         (lead4_bits << 1) | (lead4_bits << 2) | (lead4_bits << 3);
144:     const uint64_t continuation_bits = static_cast<uint64_t>(continuation);
145:     if (continuation_bits != (expected | pending)) {
146:       return false;
147:     }
148: 
149:     // Preserve expected continuations beyond this block for the next block or tail.
150:     pending = (lead2_bits >> 63) |
151:               (lead3_bits >> 63) | (lead3_bits >> 62) |
152:               (lead4_bits >> 63) | (lead4_bits >> 62) | (lead4_bits >> 61);
153:     offset += 64;
154:   }
155: 
156:   return validate_utf8_scalar(bytes, length, offset,
157:                               static_cast<uint32_t>(pending));
158: }
159: #endif
160: 
161: static bool validate_utf8(const char *input, size_t length) {
162:   const unsigned char *bytes = reinterpret_cast<const unsigned char *>(input);
163: #if UTF8_HAS_AVX512_TARGET
164:   if (length >= 64) {
165:     return validate_utf8_avx512(bytes, length);
166:   }
167: #endif
168:   return validate_utf8_scalar(bytes, length, 0, 0);
169: }
170: 
171: extern "C" void run(const void *input1, const void *input2, void *output,
172:                     int n, int parameter, int threads) {
173:   *(uint32_t *)output = validate_utf8((const char *)input1, n);
174: }

